 "content": "def transform(grid):
    """Turn each embedded red marker in a green field into a 3x3 halo."""
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            # The intended markers replace cells inside a solid green object;
            # background distractors can touch an object at just one edge.
            adjacent_green = sum(
                0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
            )
            if adjacent_green >= 2:
                centers.append((r, c))

    out = [row[:] for row in grid]
    for r, c in centers:
        for nr in range(max(0, r - 1), min(h, r + 2)):
            for nc in range(max(0, c - 1), min(w, c + 2)):
                if grid[nr][nc] != 2:
                    out[nr][nc] = 1
    return out
